.left-pane, .right-pane {
    position: absolute !important;
}

.ag-body-viewport.ag-layout-normal.ag-row-no-animation {
    margin-top: 38px !important;
}

.ui-menu.ui-widget.ui-widget-content.ui-corner-all.ui-menu-dynamic.ui-shadow {
    display: block !important;
}

/* Header user icon */
a.btn {
    background: no-repeat !important;
}

bg-pane#leftPane {
    width: 177px !important;
    overflow: auto;
}

bg-pane#rightPane {
    left: 177px;
    padding-left: 15px;
    border-left: 1px solid #DDD;
}

.kdx-page-header
{
    padding: 5px;
}
.kdx-toolbar-left
{
    height:100%;
    /* border:1px solid #ced4da; */
    border-radius: 5px;
}
button.btn.btn-icon.btn-xs {
  margin-left: 2px !important;
  border: 1px solid !important;
  border-color: #DDDDDD !important;
  border-radius: 5px !important;
}
.ng-tabs ul, .scroll_tabs_container div.scroll_tab_inner {
  height: 36px !important;
}
button.btn.btn-icon.btn-xs {
  border: 1px solid #334C66!important;
  background-color: #6699CC!important;
  color: #FFFFFF !important;
  max-width: 30px !important;
  max-height: 30px !important;
  margin-right: 4px;
}
button.btn.btn-icon.btn-xs:hover {
  background-color: #334C66!important;
}
.kdx-toolbar .btn i {
  position: absolute;
  top: 21%;
  left: 30%;
  font-size: 13px !important;
}
.kdx-toolbar .kdx-toolbar-left {
  top: 3px;
}
button.btn.btn-icon.btn-xs
{
    height:100%;
    border:none;
}

.content-wrapper {
    padding: 0px;
}

.menu-btn{
  z-index: 3;
}

/* Splitter adjustment design start*/
.hideLeftPane{
  left: -16px !important;
}

.showLeftPane{
  left: 250px !important;
}

.leftMenuSplitter{
  left: 15px;
}
/* Splitter adjustment design end*/

/* Remove blank space for right panal */
kd-splitter.kdx-split-panes.has-page-header.has-breadcrumb {
  top: -10px !important;
}

.kdx-item-icon {
  background: none!important;
  border: 0!important;
  color: #999;
  padding: 0 10px px;
  font-size: 78px;
}

